const listAccessibleStays = `-- name: ListAccessibleStays :many
SELECT
  s.id,
  s.accommodation_id,
  s.status,
  s.planned_arrival_on,
  s.planned_departure_on,
  s.expected_guest_count,
  (
    SELECT count(*)::integer
    FROM core.visitors AS v
    WHERE v.stay_id = s.id
  ) AS visitor_count,
  s.checked_in_at,
  s.checked_out_at,
  s.cancelled_at,
  s.no_show_at,
  s.cancellation_reason_code,
  s.no_show_reason_code,
  s.version,
  s.created_at,
  s.updated_at
FROM core.stays AS s
JOIN core.memberships AS m
  ON m.accommodation_id = s.accommodation_id
WHERE m.oidc_issuer = $1
  AND m.oidc_subject = $2
  AND m.active = true
  AND (
    $3::uuid IS NULL
    OR s.accommodation_id = $3::uuid
  )
  AND (
    $4::core.stay_status IS NULL
    OR s.status = $4::core.stay_status
  )
  AND (
    $5::date IS NULL
    OR s.planned_arrival_on >= $5::date
  )
  AND (
    $6::date IS NULL
    OR s.planned_arrival_on <= $6::date
  )
  AND (
    $7::timestamptz IS NULL
    OR (s.created_at, s.id) < (
      $7::timestamptz,
      $8::uuid
    )
  )
ORDER BY s.created_at DESC, s.id DESC
LIMIT $9
`

