	rows, err := q.db.Query(ctx, listAccessibleStays,
		arg.OidcIssuer,
		arg.OidcSubject,
		arg.AccommodationID,
		arg.StayStatus,
		arg.ArrivalFrom,
		arg.ArrivalTo,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAccessibleStaysRow{}
	for rows.Next() {
		var i ListAccessibleStaysRow
		if err := rows.Scan(
			&i.ID,
			&i.AccommodationID,
			&i.Status,
			&i.PlannedArrivalOn,
			&i.PlannedDepartureOn,
			&i.ExpectedGuestCount,
			&i.VisitorCount,
			&i.CheckedInAt,
			&i.CheckedOutAt,
			&i.CancelledAt,
			&i.NoShowAt,
			&i.CancellationReasonCode,
			&i.NoShowReasonCode,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
